// Package calc evaluates one 64-bit signed integer expression per line of standard input.
// See the "calc" section of SPEC.md.
package calc

import "base:intrinsics"
import "core:bufio"
import "core:bytes"
import "core:fmt"
import "core:os"
import "core:strconv"

import "../input"

// run is the entry point for `app calc`. It reads standard input, writes standard output,
// and returns normally so that the process exits with status 0.
run :: proc() {
	data, read_err := input.read_all(os.stdin)
	if read_err != nil {
		fmt.eprintln("calc: failed to read standard input:", read_err)
		return
	}
	defer delete(data)

	out: bufio.Writer
	bufio.writer_init(&out, os.to_stream(os.stdout), 64 * 1024)
	defer bufio.writer_destroy(&out)
	defer bufio.writer_flush(&out)

	ev: Evaluator
	defer evaluator_destroy(&ev)

	rest := data
	for len(rest) > 0 {
		line: []byte
		if i := bytes.index_byte(rest, '\n'); i >= 0 {
			line, rest = rest[:i], rest[i + 1:]
		} else {
			line, rest = rest, nil
		}

		if is_blank(line) {
			continue
		}

		if value, ok := evaluate(&ev, line); ok {
			digits: [32]byte
			bufio.writer_write_string(&out, strconv.write_int(digits[:], value, 10))
		} else {
			bufio.writer_write_string(&out, "error")
		}
		bufio.writer_write_byte(&out, '\n')
	}
}

// Op is an operator held on the evaluator's operator stack.
Op :: enum u8 {
	Open_Paren,
	Add,
	Sub,
	Mul,
	Div,
	Rem,
	Neg,
}

// precedence orders operators for reduction; a higher value binds tighter.
// Open_Paren has the lowest so that reductions never cross it.
@(rodata)
precedence := [Op]u8 {
	.Open_Paren = 0,
	.Add        = 1,
	.Sub        = 1,
	.Mul        = 2,
	.Div        = 2,
	.Rem        = 2,
	.Neg        = 3,
}

// Evaluator holds the operand and operator stacks. They are reused across lines so that
// evaluating many expressions does not allocate per line. Parsing is iterative (operator
// precedence with explicit stacks), so arbitrarily deep nesting cannot overflow the call stack.
Evaluator :: struct {
	values: [dynamic]i64,
	ops:    [dynamic]Op,
}

evaluator_destroy :: proc(ev: ^Evaluator) {
	delete(ev.values)
	delete(ev.ops)
}

// evaluate parses and evaluates one expression. It returns ok = false on any syntax error,
// division or remainder by zero, or 64-bit overflow.
evaluate :: proc(ev: ^Evaluator, line: []byte) -> (value: i64, ok: bool) {
	clear(&ev.values)
	clear(&ev.ops)

	// The parser alternates between expecting an operand (a number, '(' or unary '-')
	// and expecting an operator (a binary operator, ')' or the end of the line).
	expect_operand := true
	i := 0
	for i < len(line) {
		c := line[i]
		switch {
		case c == ' ' || c == '\t':
			i += 1

		case expect_operand:
			switch c {
			case '0' ..= '9':
				n: i64
				n, i = parse_number(line, i) or_return
				append(&ev.values, n)
				expect_operand = false
			case '(':
				append(&ev.ops, Op.Open_Paren)
				i += 1
			case '-':
				append(&ev.ops, Op.Neg)
				i += 1
			case:
				return 0, false
			}

		case c == ')':
			for {
				top := pop_safe(&ev.ops) or_return
				if top == .Open_Paren {
					break
				}
				apply(ev, top) or_return
			}
			i += 1

		case:
			op: Op
			switch c {
			case '+': op = .Add
			case '-': op = .Sub
			case '*': op = .Mul
			case '/': op = .Div
			case '%': op = .Rem
			case:     return 0, false
			}
			// All binary operators are left-associative: reduce equal precedence too.
			for len(ev.ops) > 0 && precedence[ev.ops[len(ev.ops) - 1]] >= precedence[op] {
				apply(ev, pop(&ev.ops)) or_return
			}
			append(&ev.ops, op)
			expect_operand = true
			i += 1
		}
	}

	if expect_operand {
		return 0, false
	}
	for len(ev.ops) > 0 {
		top := pop(&ev.ops)
		if top == .Open_Paren {
			return 0, false
		}
		apply(ev, top) or_return
	}
	assert(len(ev.values) == 1)
	return ev.values[0], true
}

// parse_number reads the run of decimal digits starting at line[start], failing if the
// literal exceeds the i64 range. It returns the value and the index just past the digits.
parse_number :: proc(line: []byte, start: int) -> (value: i64, end: int, ok: bool) {
	end = start
	for end < len(line) && line[end] >= '0' && line[end] <= '9' {
		overflow: bool
		if value, overflow = intrinsics.overflow_mul(value, 10); overflow {
			return
		}
		if value, overflow = intrinsics.overflow_add(value, i64(line[end] - '0')); overflow {
			return
		}
		end += 1
	}
	return value, end, true
}

// apply pops the operands of op from the value stack and pushes its result.
// The parser guarantees enough operands are present.
apply :: proc(ev: ^Evaluator, op: Op) -> (ok: bool) {
	if op == .Neg {
		top := &ev.values[len(ev.values) - 1]
		if top^ == min(i64) {
			return false
		}
		top^ = -top^
		return true
	}

	rhs := pop(&ev.values)
	lhs := &ev.values[len(ev.values) - 1]
	a, b := lhs^, rhs
	result: i64
	overflow: bool
	switch op {
	case .Add:
		result, overflow = intrinsics.overflow_add(a, b)
	case .Sub:
		result, overflow = intrinsics.overflow_sub(a, b)
	case .Mul:
		result, overflow = intrinsics.overflow_mul(a, b)
	case .Div:
		if b == 0 || (a == min(i64) && b == -1) {
			return false
		}
		result = a / b
	case .Rem:
		if b == 0 {
			return false
		}
		// min(i64) % -1 is mathematically 0 but traps on most hardware.
		result = 0 if b == -1 else a % b
	case .Open_Paren, .Neg:
		unreachable()
	}
	if overflow {
		return false
	}
	lhs^ = result
	return true
}

is_blank :: proc(line: []byte) -> bool {
	for c in line {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

// Package input provides helpers for reading program input shared by the subcommands.
package input

import "core:os"

// INITIAL_BUFFER_SIZE is the starting size of the buffer used by read_all; it doubles as needed.
INITIAL_BUFFER_SIZE :: 1 << 20

// read_all reads `f` until end of file. Unlike os.read_entire_file it does not trust the
// reported file size, which for a pipe on some platforms is only the currently buffered amount.
// The returned slice is allocated with `allocator` and owned by the caller.
read_all :: proc(f: ^os.File, allocator := context.allocator) -> (data: []byte, err: os.Error) {
	buf := make([dynamic]byte, INITIAL_BUFFER_SIZE, allocator) or_return
	total := 0
	for {
		if total == len(buf) {
			if rerr := non_zero_resize(&buf, 2 * len(buf)); rerr != nil {
				delete(buf)
				return nil, rerr
			}
		}
		n, rerr := os.read(f, buf[total:])
		total += n
		if rerr == .EOF || rerr == .Broken_Pipe || (rerr == nil && n == 0) {
			break
		}
		if rerr != nil {
			delete(buf)
			return nil, rerr
		}
	}
	return buf[:total], nil
}

// Package lru simulates an LRU cache driven by commands read from standard input.
// See the "lru" section of SPEC.md.
package lru

import "core:bufio"
import "core:fmt"
import "core:io"
import "core:os"
import "core:strconv"
import "core:strings"

import "../input"

// run is the entry point for `app lru`. It reads standard input, writes standard output,
// and returns normally so that the process exits with status 0.
run :: proc() {
	data, err := input.read_all(os.stdin)
	if err != nil {
		fmt.eprintln("lru: failed to read standard input:", err)
		return
	}
	defer delete(data)

	out: bufio.Writer
	bufio.writer_init(&out, os.to_writer(os.stdout), 64 * 1024)
	defer bufio.writer_destroy(&out)

	simulate(string(data), bufio.writer_to_stream(&out))

	if ferr := bufio.writer_flush(&out); ferr != nil {
		fmt.eprintln("lru: failed to write standard output:", ferr)
	}
}

// simulate executes the program in `input` (capacity line followed by commands) and writes
// each command's output to `w`. Keys and values are slices of `input`, which must outlive the call.
simulate :: proc(input: string, w: io.Writer) {
	rest := input
	first, _ := next_line(&rest)

	capacity, ok := strconv.parse_int(strings.trim_space(first), 10)
	if !ok || capacity < 1 {
		// The spec guarantees a valid capacity; degrade to the smallest legal cache otherwise.
		capacity = 1
	}

	cache: Cache
	cache_init(&cache, capacity)
	defer cache_destroy(&cache)

	for line in next_line(&rest) {
		tokens: [3]string
		n := tokenize(line, tokens[:])

		switch {
		case n == 3 && tokens[0] == "SET":
			cache_set(&cache, tokens[1], tokens[2])
		case n == 2 && tokens[0] == "GET":
			if value, found := cache_get(&cache, tokens[1]); found {
				io.write_string(w, value)
			} else {
				io.write_string(w, "NULL")
			}
			io.write_byte(w, '\n')
		case n == 2 && tokens[0] == "DEL":
			io.write_string(w, "1\n" if cache_del(&cache, tokens[1]) else "0\n")
		case n == 1 && tokens[0] == "SIZE":
			io.write_int(w, cache.count)
			io.write_byte(w, '\n')
		}
		// Blank lines and malformed commands produce no output.
	}
}

// next_line pops the next line from `s`, stripping the `\n` terminator and any trailing `\r`.
// It reports false once `s` is exhausted; a final line without `\n` is still returned.
next_line :: proc(s: ^string) -> (line: string, ok: bool) {
	if len(s^) == 0 {
		return "", false
	}
	if i := strings.index_byte(s^, '\n'); i >= 0 {
		line, s^ = s[:i], s[i + 1:]
	} else {
		line, s^ = s^, ""
	}
	return strings.trim_right(line, "\r"), true
}

// tokenize splits `line` on spaces into `tokens` and returns the number of tokens found.
// Empty tokens are skipped. If the line holds more tokens than fit, len(tokens)+1 is returned
// so that callers can reject it as malformed.
tokenize :: proc(line: string, tokens: []string) -> int {
	n := 0
	rest := line
	for len(rest) > 0 {
		token := rest
		if i := strings.index_byte(rest, ' '); i >= 0 {
			token, rest = rest[:i], rest[i + 1:]
		} else {
			rest = ""
		}
		if len(token) == 0 {
			continue
		}
		if n == len(tokens) {
			return n + 1
		}
		tokens[n] = token
		n += 1
	}
	return n
}

// Node is an entry of the cache's intrusive doubly linked recency list.
// Links are indices into `Cache.nodes`; index SENTINEL is the list head.
Node :: struct {
	key:   string,
	value: string,
	prev:  i32,
	next:  i32,
}

SENTINEL :: 0

// Cache is a fixed-capacity LRU cache. Nodes live in a pool and are linked into a circular list
// through the sentinel: `nodes[SENTINEL].next` is the most recently used entry and
// `nodes[SENTINEL].prev` the least recently used. Slots freed by DEL are reused via `free`.
Cache :: struct {
	index:    map[string]i32,
	nodes:    [dynamic]Node,
	free:     [dynamic]i32,
	capacity: int,
	count:    int,
}

cache_init :: proc(c: ^Cache, capacity: int, allocator := context.allocator) {
	// Reserve modestly up front; the pool and map grow on demand so a huge capacity
	// with few commands stays cheap.
	initial := min(capacity, 1 << 16) + 1
	c.capacity = capacity
	c.count = 0
	c.index = make(map[string]i32, initial, allocator)
	c.nodes = make([dynamic]Node, 0, initial, allocator)
	c.free = make([dynamic]i32, allocator)
	append(&c.nodes, Node{prev = SENTINEL, next = SENTINEL})
}

cache_destroy :: proc(c: ^Cache) {
	delete(c.index)
	delete(c.nodes)
	delete(c.free)
	c^ = {}
}

// cache_get returns the value stored under `key` and marks it most recently used.
cache_get :: proc(c: ^Cache, key: string) -> (value: string, found: bool) {
	i := c.index[key] or_return
	move_to_front(c, i)
	return c.nodes[i].value, true
}

// cache_set inserts or overwrites `key`, marks it most recently used, and evicts the least
// recently used entry if the cache would exceed its capacity.
cache_set :: proc(c: ^Cache, key, value: string) {
	if i, found := c.index[key]; found {
		c.nodes[i].value = value
		move_to_front(c, i)
		return
	}

	i: i32
	if c.count == c.capacity {
		// Evict the LRU entry and reuse its slot for the new key.
		i = c.nodes[SENTINEL].prev
		delete_key(&c.index, c.nodes[i].key)
		unlink(c, i)
		c.count -= 1
	} else if len(c.free) > 0 {
		i = pop(&c.free)
	} else {
		i = i32(len(c.nodes))
		append(&c.nodes, Node{})
	}

	c.nodes[i].key = key
	c.nodes[i].value = value
	link_front(c, i)
	c.index[key] = i
	c.count += 1
}

// cache_del removes `key` and reports whether it was present.
cache_del :: proc(c: ^Cache, key: string) -> bool {
	i := c.index[key] or_return
	delete_key(&c.index, key)
	unlink(c, i)
	c.nodes[i] = {}
	append(&c.free, i)
	c.count -= 1
	return true
}

@(private)
unlink :: proc(c: ^Cache, i: i32) {
	n := &c.nodes[i]
	c.nodes[n.prev].next = n.next
	c.nodes[n.next].prev = n.prev
}

@(private)
link_front :: proc(c: ^Cache, i: i32) {
	first := c.nodes[SENTINEL].next
	c.nodes[i].prev = SENTINEL
	c.nodes[i].next = first
	c.nodes[first].prev = i
	c.nodes[SENTINEL].next = i
}

@(private)
move_to_front :: proc(c: ^Cache, i: i32) {
	if c.nodes[SENTINEL].next == i {
		return
	}
	unlink(c, i)
	link_front(c, i)
}

// Command suite dispatches its first argument to one of three independent subcommands.
// Each subcommand lives in its own package under src/ and exposes a single `run` entry point.
package main

import "core:fmt"
import "core:os"

import "calc"
import "lru"
import "wordfreq"

Command :: struct {
	name: string,
	run:  proc(),
}

COMMANDS :: [?]Command {
	{"wordfreq", wordfreq.run},
	{"lru", lru.run},
	{"calc", calc.run},
}

main :: proc() {
	if len(os.args) < 2 {
		usage()
	}

	name := os.args[1]
	for command in COMMANDS {
		if command.name == name {
			command.run()
			return
		}
	}

	fmt.eprintfln("app: unknown subcommand %q", name)
	usage()
}

usage :: proc() -> ! {
	fmt.eprintln("usage: app <subcommand>")
	fmt.eprintln("subcommands:")
	for command in COMMANDS {
		fmt.eprintfln("  %s", command.name)
	}
	os.exit(2)
}

// Package wordfreq prints the 10 most frequent words read from standard input.
// See the "wordfreq" section of SPEC.md.
package wordfreq

import "core:fmt"
import "core:mem/virtual"
import "core:os"
import "core:strings"

// TOP_N is the maximum number of words printed.
TOP_N :: 10

// READ_CHUNK_SIZE is how many bytes of standard input are processed at a time.
READ_CHUNK_SIZE :: 1 << 20

// Word_Count pairs a lowercase word with the number of times it occurred.
Word_Count :: struct {
	word:  string,
	count: int,
}

// Counter tallies lowercase words. Keys are owned by `arena`, so the whole table is freed at once.
Counter :: struct {
	counts: map[string]int,
	arena:  virtual.Arena,
}

counter_init :: proc(c: ^Counter) -> virtual.Allocator_Error {
	virtual.arena_init_growing(&c.arena) or_return
	c.counts = make(map[string]int)
	return nil
}

counter_destroy :: proc(c: ^Counter) {
	delete(c.counts)
	virtual.arena_destroy(&c.arena)
}

// counter_add counts one occurrence of `word`, which must already be lowercase.
// `word` may point into a transient buffer: it is copied the first time it is seen.
counter_add :: proc(c: ^Counter, word: []byte) {
	key_ptr, value_ptr, just_inserted, err := map_entry(&c.counts, string(word))
	if err != nil {
		return
	}
	if just_inserted {
		key_ptr^ = strings.clone(string(word), virtual.arena_allocator(&c.arena))
	}
	value_ptr^ += 1
}

// count_stream reads `f` to the end, counting every word in it.
// A word split across two reads is reassembled in a carry buffer.
count_stream :: proc(c: ^Counter, f: ^os.File) {
	buf := make([]byte, READ_CHUNK_SIZE)
	defer delete(buf)
	carry: [dynamic]byte
	defer delete(carry)

	for {
		n, err := os.read(f, buf)
		chunk := buf[:n]

		// Start of the word in progress within `chunk`, or -1 between words.
		// A word carried over from the previous read continues at the start of this chunk.
		start := 0 if len(carry) > 0 else -1
		for &b, i in chunk {
			if is_letter(b) {
				b |= 0x20 // ASCII lowercase.
				if start < 0 {
					start = i
				}
			} else if start >= 0 {
				word := chunk[start:i]
				if len(carry) > 0 {
					append(&carry, ..word)
					counter_add(c, carry[:])
					clear(&carry)
				} else {
					counter_add(c, word)
				}
				start = -1
			}
		}
		if start >= 0 {
			append(&carry, ..chunk[start:])
		}

		if err != nil {
			break
		}
	}

	if len(carry) > 0 {
		counter_add(c, carry[:])
	}
}

is_letter :: #force_inline proc "contextless" (b: byte) -> bool {
	return (b | 0x20) - 'a' < 26
}

// ranks_before reports whether `a` is listed before `b`: higher count first, then word ascending.
ranks_before :: proc(a, b: Word_Count) -> bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

// top_words writes the highest-ranked words into `out`, best first, and returns how many it wrote.
top_words :: proc(c: ^Counter, out: []Word_Count) -> int {
	n := 0
	for word, count in c.counts {
		entry := Word_Count{word, count}
		if n == len(out) && !ranks_before(entry, out[n - 1]) {
			continue
		}
		// Insertion into the sorted prefix, dropping the last entry when full.
		i := min(n, len(out) - 1)
		for i > 0 && ranks_before(entry, out[i - 1]) {
			out[i] = out[i - 1]
			i -= 1
		}
		out[i] = entry
		n = min(n + 1, len(out))
	}
	return n
}

// run is the entry point for `app wordfreq`. It reads standard input, writes standard output,
// and returns normally so that the process exits with status 0.
run :: proc() {
	counter: Counter
	if err := counter_init(&counter); err != nil {
		fmt.eprintln("wordfreq: out of memory:", err)
		return
	}
	defer counter_destroy(&counter)

	count_stream(&counter, os.stdin)

	top: [TOP_N]Word_Count
	n := top_words(&counter, top[:])

	sb := strings.builder_make()
	defer strings.builder_destroy(&sb)
	for entry in top[:n] {
		fmt.sbprintf(&sb, "%d %s\n", entry.count, entry.word)
	}
	os.write_string(os.stdout, strings.to_string(sb))
}
